/**
 * An API that handles how to represent entities in the interface.
 *
 * @remarks
 *
 * There are several ways to consume this API depending on context:
 *
 * - In React components, use the {@link useEntityPresentation} hook to get a
 *   reactive presentation snapshot that updates over time.
 *
 * - For simple inline rendering, use the {@link EntityDisplayName} component
 *   which wraps the hook and renders a styled entity name with optional icon
 *   and tooltip.
 *
 * - In non-React contexts such as sort comparators or data mappers, use the
 *   {@link entityPresentationSnapshot} helper for synchronous access, or
 *   the API directly via `forEntity().promise` in async loaders.
 *
 * @public
 */
declare const entityPresentationApiRef: ApiRef<EntityPresentationApi>;
/**
 * The visual presentation of an entity reference at some point in time.
 *
 * @public
 */
interface EntityRefPresentationSnapshot {
    /**
     * The ref to the entity that this snapshot represents.
     *
     * @remarks
     *
     * Note that when the input data was broken or had missing vital pieces of
     * information, this string may contain placeholders such as "unknown". You
     * can therefore not necessarily assume that the ref is completely valid and
     * usable for example for forming a clickable link to the entity.
     */
    entityRef: string;
    /**
     * A string that can be used as a plain representation of the entity, for
     * example in a header or a link.
     *
     * @remarks
     *
     * The title may be short and not contain all of the information that the
     * entity holds. When rendering the primary title, you may also want to
     * make sure to add more contextual information nearby such as the icon or
     * secondary title, since the primary could for example just be the
     * `metadata.name` of the entity which might be ambiguous to the reader.
     */
    primaryTitle: string;
    /**
     * Optionally, some additional textual information about the entity, to be
     * used as a clarification on top of the primary title.
     *
     * @remarks
     *
     * This text can for example be rendered in a tooltip or be used as a
     * subtitle. It may not be sufficient to display on its own; it should
     * typically be used in conjunction with the primary title. It can contain
     * such information as the entity ref and/or a `spec.type` etc.
     */
    secondaryTitle?: string;
    /**
     * Optionally, an icon that represents the kind/type of entity.
     *
     * @remarks
     *
     * This icon should ideally be easily recognizable as the kind of entity, and
     * be used consistently throughout the Backstage interface. It can be rendered
     * both in larger formats such as in a header, or in smaller formats such as
     * inline with regular text, so bear in mind that the legibility should be
     * high in both cases.
     *
     * A value of `false` here indicates the desire to not have an icon present
     * for the given implementation. A value of `undefined` leaves it at the
     * discretion of the display layer to choose what to do (such as for example
     * showing a fallback icon).
     */
    Icon?: IconComponent | undefined | false;
}
/**
 * The visual presentation of an entity reference.
 *
 * @public
 */
interface EntityRefPresentation {
    /**
     * The representation that's suitable to use for this entity right now.
     */
    snapshot: EntityRefPresentationSnapshot;
    /**
     * Some presentation implementations support emitting updated snapshots over
     * time, for example after retrieving additional data from the catalog or
     * elsewhere.
     */
    update$?: Observable<EntityRefPresentationSnapshot>;
    /**
     * A promise that resolves to a usable entity presentation.
     */
    promise: Promise<EntityRefPresentationSnapshot>;
}
/**
 * An API that decides how to visually represent entities in the interface.
 *
 * @remarks
 *
 * Most consumers will not need to interact with this interface directly.
 * Instead, use one of the following:
 *
 * - {@link useEntityPresentation} — React hook for reactive presentation data.
 *
 * - {@link EntityDisplayName} — React component that renders an entity name
 *   with optional icon and tooltip.
 *
 * For non-React contexts, use the {@link entityPresentationSnapshot} helper
 * for synchronous access, or the API directly via `forEntity().promise`
 * for async contexts.
 *
 * Implement this interface to customize how entities are displayed throughout
 * the Backstage interface.
 *
 * @public
 */
interface EntityPresentationApi {
    /**
     * Fetches the presentation for an entity.
     *
     * @param entityOrRef - Either an entity, or a string ref to it. If you pass
     *   in an entity, it is assumed that it is not a partial one - i.e. only pass
     *   in an entity if you know that it was fetched in such a way that it
     *   contains all of the fields that the representation renderer needs.
     * @param context - Contextual information that may affect the presentation.
     */
    forEntity(entityOrRef: Entity | string, context?: {
        defaultKind?: string;
        defaultNamespace?: string;
    }): EntityRefPresentation;
}

/**
 * Returns the default representation of an entity.
 *
 * @remarks
 *
 * This is a synchronous helper that extracts a display name from an
 * already-loaded entity or entity ref. It resolves `primaryTitle` as the
 * first available value among `spec.profile.displayName`, `metadata.title`,
 * and a shortened entity ref string.
 *
 * This function is primarily used as the internal fallback within the
 * {@link EntityPresentationApi} when no custom implementation is registered.
 * In React components, use the {@link useEntityPresentation} hook or the
 * {@link EntityDisplayName} component. In non-React contexts, use
 * {@link entityPresentationSnapshot} which respects custom presentation
 * overrides and falls back to this function when no API is registered.
 *
 * @public
 * @param entityOrRef - Either an entity, or a ref to it.
 * @param context - Contextual information that may affect the presentation.
 */
declare function defaultEntityPresentation(entityOrRef: Entity | CompoundEntityRef | string, context?: {
    defaultKind?: string;
    defaultNamespace?: string;
}): EntityRefPresentationSnapshot;

/**
 * Returns a synchronous presentation snapshot for an entity in non-React
 * contexts.
 *
 * @remarks
 *
 * This is the synchronous, non-React counterpart to
 * {@link useEntityPresentation}. It handles `Entity`, `CompoundEntityRef`,
 * and string ref inputs uniformly, using the provided
 * {@link EntityPresentationApi} when available and falling back to
 * {@link defaultEntityPresentation} otherwise.
 *
 * Because this function is synchronous, it uses cached data from the
 * presentation API (via `.snapshot`). If the entity has been seen before,
 * the snapshot will contain the full resolved title; otherwise it falls
 * back to what can be extracted from the ref alone. This is the correct
 * trade-off for sort comparators, column factories, filter callbacks, and
 * data mappers where a synchronous return value is required.
 *
 * In async contexts such as data loaders where you can `await`, prefer
 * using the {@link EntityPresentationApi} directly via
 * `forEntity().promise` for the richest possible presentation.
 *
 * @public
 * @param entityOrRef - An entity, a compound entity ref, or a string entity ref.
 * @param context - Optional context that may affect the presentation.
 * @param entityPresentationApi - Optional presentation API instance. When not
 *   provided, falls back to {@link defaultEntityPresentation}.
 */
declare function entityPresentationSnapshot(entityOrRef: Entity | CompoundEntityRef | string, context?: {
    defaultKind?: string;
    defaultNamespace?: string;
}, entityPresentationApi?: EntityPresentationApi): EntityRefPresentationSnapshot;

/**
 * Returns information about how to represent an entity in the interface.
 *
 * @remarks
 *
 * This hook subscribes to the {@link EntityPresentationApi} and returns a
 * snapshot that may update over time as richer data is fetched (for example,
 * resolving `metadata.title` from a string entity ref). If no presentation
 * API is registered, it falls back to {@link defaultEntityPresentation}.
 *
 * For simple inline rendering, consider using the {@link EntityDisplayName}
 * component instead, which wraps this hook with icon and tooltip support.
 *
 * For non-React contexts such as sort comparators or data mappers, use
 * {@link entityPresentationSnapshot}.
 *
 * @public
 * @param entityOrRef - The entity to represent, or an entity ref to it. If you
 *   pass in an entity, it is assumed that it is NOT a partial one - i.e. only
 *   pass in an entity if you know that it was fetched in such a way that it
 *   contains all of the fields that the representation renderer needs.
 * @param context - Optional context that control details of the presentation.
 * @returns A snapshot of the entity presentation, which may change over time
 */
declare function useEntityPresentation(entityOrRef: Entity | CompoundEntityRef | string, context?: {
    defaultKind?: string;
    defaultNamespace?: string;
}): EntityRefPresentationSnapshot;

